// S179: adopt claude-batch.mjs for non-interactive bulk Claude work
// 50% token cost reduction vs synchronous Messages API
import { buildBatchRequest, runBatch } from '../scripts/lib/claude-batch.mjs';
// OR from studio-ops path:
import { buildBatchRequest, runBatch } from 'vaultspark-studio-ops/scripts/lib/claude-batch.mjs';

// Example usage:
const reqs = items.map(item => buildBatchRequest({
  customId: item.id,
  model: MODELS.haiku,          // cheapest model — batch discount stacks with cache
  maxTokens: 1024,
  cachedSystemPrefix: SYSTEM,   // stable prefix → cache_control applied (free reads)
  messages: [{ role: 'user', content: item.prompt }],
}));
const { results, usage } = await runBatch(reqs, { logAs: 'your-script-name' });
